// ===== C: the daily report on Home, in place of the dashboards =====
const RW = 376;
// line against a plan: ink line, dashed plan, the last point red when it is off plan
function planLine(vals, plan, o) {
  o = o || {}; const h = o.h || 64, lo = o.min, hi = o.max, y = (v) => 4 + (1 - (v - lo) / (hi - lo)) * (h - 8);
  const pts = vals.map((v, i) => [(i / (vals.length - 1)) * RW, y(v)]), d = pts.map((p, i) => (i ? 'L' : 'M') + p[0].toFixed(1) + ' ' + p[1].toFixed(1)).join(' '), e = pts[pts.length - 1];
  const band = o.band ? '<rect x="' + (o.band[0] * RW).toFixed(1) + '" y="0" width="' + ((o.band[1] - o.band[0]) * RW).toFixed(1) + '" height="' + h + '" fill="' + K.red + '" fill-opacity=".07"></rect><text x="' + ((o.band[0] + o.band[1]) / 2 * RW).toFixed(1) + '" y="12" text-anchor="middle" font-family="Geist, system-ui" font-size="10.5" fill="' + K.red + '">' + o.bandLabel + '</text>' : '';
  return '<svg viewBox="0 0 ' + RW + ' ' + (h + 16) + '" style="display: block; width: ' + RW + 'px; height: ' + (h + 16) + 'px; overflow: visible;">' + band + '<line x1="0" x2="' + RW + '" y1="' + y(plan).toFixed(1) + '" y2="' + y(plan).toFixed(1) + '" stroke="' + K.faint + '" stroke-dasharray="4 4"></line><text x="' + RW + '" y="' + (y(plan) + 13).toFixed(1) + '" text-anchor="end" font-family="Geist, system-ui" font-size="10.5" fill="' + K.muted + '">plan ' + plan + (o.unit || '') + '</text><path d="' + d + '" fill="none" stroke="' + K.ink + '" stroke-width="1.8" stroke-linejoin="round"></path><circle cx="' + e[0].toFixed(1) + '" cy="' + e[1].toFixed(1) + '" r="3.5" fill="' + (o.off ? K.red : K.ink) + '"></circle>' + (o.axis ? o.axis.map((a, i) => '<text x="' + (i === 0 ? 0 : i === o.axis.length - 1 ? RW : RW / 2) + '" y="' + (h + 14) + '" text-anchor="' + (i === 0 ? 'start' : i === o.axis.length - 1 ? 'end' : 'middle') + '" font-family="Geist, system-ui" font-size="10.5" fill="' + K.faint + '">' + a + '</text>').join('') : '') + '</svg>';
}
// bars by day against a normal level
function dayBars(vals, normal, labels) {
  const h = 58, hi = Math.max(...vals, normal) * 1.08, bw = RW / vals.length, y = (v) => h - (v / hi) * h;
  return '<svg viewBox="0 0 ' + RW + ' ' + (h + 16) + '" style="display: block; width: ' + RW + 'px; height: ' + (h + 16) + 'px; overflow: visible;">' + vals.map((v, i) => { const low = v < normal * 0.97; return '<rect x="' + (i * bw + 5).toFixed(1) + '" y="' + y(v).toFixed(1) + '" width="' + (bw - 10).toFixed(1) + '" height="' + (h - y(v)).toFixed(1) + '" rx="3" fill="' + (low ? K.red : K.ink) + '" fill-opacity="' + (low ? 0.85 : 0.18) + '"></rect><text x="' + (i * bw + bw / 2).toFixed(1) + '" y="' + (h + 13) + '" text-anchor="middle" font-family="Geist, system-ui" font-size="10.5" fill="' + K.faint + '">' + labels[i] + '</text>'; }).join('') + '<line x1="0" x2="' + RW + '" y1="' + y(normal).toFixed(1) + '" y2="' + y(normal).toFixed(1) + '" stroke="' + K.faint + '" stroke-dasharray="4 4"></line></svg>';
}
const linkTo = (s) => '<span style="' + st({ display: 'inline-flex', alignItems: 'center', gap: '2px', fontSize: '13px', fontWeight: 500, color: K.ink }) + '">' + esc(s) + icon(I.chev, 13) + '</span>';
const story = (n, finding, chart, why, link) => '<div style="' + st({ padding: '14px 16px', borderTop: n ? '1px solid ' + K.line : '0' }) + '">' + t(finding, { fontSize: '15px', lineHeight: '21px', fontWeight: 600, whiteSpace: 'normal', display: 'block' }) + '<div style="margin: 10px 0 8px;">' + chart + '</div>' + t(why, { fontSize: '13px', lineHeight: '19px', color: K.muted, whiteSpace: 'normal', display: 'block' }) + '<div style="margin-top: 8px;">' + linkTo(link) + '</div></div>';
const check = 'm5 12 5 5 9-10';
function reportCard(quiet) {
  const head = '<div style="' + st({ padding: '14px 16px 12px', borderBottom: '1px solid ' + K.line }) + '"><div style="' + st({ display: 'flex', alignItems: 'center', gap: '8px' }) + '"><span style="' + st({ display: 'inline-flex', width: '22px', height: '22px', alignItems: 'center', justifyContent: 'center', borderRadius: '6px', background: '#1B211C', color: '#FFFFFF', fontSize: '9.5px', fontWeight: 700 }) + '">GM</span>' + t('Daily report', { fontSize: '15px', fontWeight: 600 }) + t('Thu 5 Nov · 06:00', { fontSize: '12.5px', color: K.faint }) + '<span style="flex: 1;"></span>' + linkTo('Full report') + '</div>' +
    t(quiet ? 'All on plan. Nothing on the farm needs you today.' : 'Mostly on plan. Two things to watch: piglet losses after the heat-lamp fault, and Gestation 2 eating less.', { fontSize: '16px', lineHeight: '23px', fontWeight: 500, whiteSpace: 'normal', display: 'block', marginTop: '10px', letterSpacing: '-.005em' }) + '</div>';
  const loss = [10.4, 9.9, 10.8, 9.6, 9.2, 9.8, 8.9, 9.4, 8.7, 9.1, 8.8, 9.0, 9.8];
  const stories = quiet ? '' :
    story(0, 'Piglet losses 9.8% this week, against 8% planned', planLine([7.8, 8.1, 7.6, 8.0, 7.9, 8.2, 8.4, 9.6, 11.2, 10.8, 9.4, 9.8], 8, { min: 6.5, max: 12, off: true, unit: '%', band: [0.58, 0.82], bandLabel: 'heat-lamp fault', axis: ['12 weeks ago', 'this week'] }), '11 of the 17 losses were crushing in Farrowing 2 and 3 while the lamps were down (21–26 Oct). One loss since the fix.', 'Ask Vet') +
    story(1, 'Gestation 2 ate 6% less for three days', dayBars([2.62, 2.6, 2.63, 2.61, 2.46, 2.45, 2.47], 2.6, ['Fri', 'Sat', 'Sun', 'Mon', 'Tue', 'Wed', 'Thu']), 'In step with low pressure on water line B. Gao Feng checks it this morning.', 'See it in the Farm view') +
    story(2, 'Batch 33 starts farrowing Friday, about 6 litters', planLine([0, 0, 0, 0, 0, 0, 1, 3, 6], 6, { min: 0, max: 8, axis: ['today', 'Fri', 'Sat'], h: 44 }).replace('plan 6', 'expected 6'), 'Farrowing 1 is washed and drying. Production asks whether to keep it there (in your Inbox).', 'Open Batch 33');
  const onPlan = '<div style="' + st({ display: 'flex', alignItems: 'flex-start', gap: '8px', padding: '12px 16px', borderTop: quiet ? '0' : '1px solid ' + K.line, background: '#FAFBF8' }) + '"><span style="' + st({ display: 'inline-flex', color: '#2F7A55', marginTop: '2px' }) + '">' + icon(check, 15, 2.2) + '</span>' + t(quiet ? 'On plan: PSY 28.5, born alive 12.4, piglet losses 7.9%, feed, water, treatments, all rooms on schedule.' : 'On plan: PSY 28.5, born alive 12.4, feed elsewhere, treatments, every other room.', { fontSize: '13px', lineHeight: '19px', color: K.muted, whiteSpace: 'normal' }) + '</div>';
  return '<div style="' + st({ background: K.card, border: '1px solid ' + K.line, borderRadius: K.radius, overflow: 'hidden' }) + '">' + head + stories + onPlan + '</div>';
}
function inboxQuiet() {
  return '<div style="' + st({ background: K.card, border: '1px solid ' + K.line, borderRadius: K.radius, padding: '14px 16px' }) + '"><div style="' + st({ display: 'flex', alignItems: 'center', gap: '8px' }) + '">' + icon(I.inbox, 17) + t('Inbox', { fontSize: '15px', fontWeight: 600 }) + '<span style="flex: 1;"></span>' + t('Open', { fontSize: '13px', color: K.muted }) + '<span style="color: ' + K.faint + '; display: inline-flex;">' + icon(I.chev, 14) + '</span></div><div style="' + st({ display: 'flex', alignItems: 'baseline', gap: '8px', marginTop: '8px' }) + '">' + t('1', { fontSize: '34px', lineHeight: '40px', fontWeight: 600 }) + t('waiting · Mark Dr. Chen\'s visit', { fontSize: '14px', color: K.muted }) + '</div></div>';
}
function todayQuiet() { return todayCard().replace('>6<', '>3<').replace('of 10 jobs done', 'of 8 jobs done').replace('next: Amox, 4 sows', 'next: weigh Batch 30, 14:00'); }
const dashLink = '<div style="' + st({ display: 'flex', alignItems: 'center', gap: '8px', height: '44px', padding: '0 16px', marginTop: '10px', background: K.card, border: '1px solid ' + K.line, borderRadius: K.radius }) + '">' + t('Dashboards', { fontWeight: 500 }) + t('Production · Health · Finance', { fontSize: '12.5px', color: K.faint }) + '<span style="flex: 1;"></span><span style="color: ' + K.faint + '; display: inline-flex;">' + icon(I.chev, 14) + '</span></div>';
const paneBody = (quiet) => tabs() + '<div style="padding: 14px 30px 24px;"><div style="' + st({ display: 'flex', alignItems: 'center', gap: '8px', height: '38px', padding: '0 12px', borderRadius: '10px', background: K.card, border: '1px solid ' + K.line, color: K.muted, fontSize: '14px' }) + '">' + icon(I.search, 16) + 'Find a page or action</div><div style="' + st({ display: 'flex', flexDirection: 'column', gap: '10px', marginTop: '12px' }) + '">' + (quiet ? inboxQuiet() + todayQuiet() : inboxCard() + todayCard()) + '</div><div style="height: 18px;"></div>' + reportCard(quiet) + dashLink + '</div>';
const pane = (quiet, h) => { K = THEMES.colour; return '<div style="' + st({ width: '468px', height: h + 'px', overflow: 'hidden', background: K.bg, fontFamily: "'Geist', system-ui, sans-serif", color: K.ink, fontVariantNumeric: 'tabular-nums', borderRadius: '16px', boxShadow: '0 0 0 1px #E2E5DE' }) + '">' + paneBody(quiet) + '</div>'; };

(async () => {
  const left = await sharp(consolePng).extract({ left: 0, top: 0, width: 964, height: 900 }).jpeg({ quality: 82 }).toBuffer();
  const img = 'data:image/jpeg;base64,' + left.toString('base64');
  const consoleFrame = (quiet) => '<div style="' + st({ position: 'relative', width: '1440px', height: '900px', background: '#EEF0EA', borderRadius: '14px', overflow: 'hidden', boxShadow: '0 0 0 1px #DADFD5, 0 12px 32px rgba(17,21,17,.10)', flexShrink: 0 }) + '"><img alt="" src="' + img + '" style="position: absolute; left: 0; top: 0; width: 964px; height: 900px;"><div style="position: absolute; left: 964px; top: 8px;">' + pane(quiet, 884) + '</div></div>';
  const row = (n, label, note, quiet, fh) => '<div style="margin-top: 40px;"><div style="' + st({ fontSize: '19px', fontWeight: 600, lineHeight: '26px' }) + '">' + n + ' · ' + label + '</div><div style="' + st({ fontSize: '14px', lineHeight: '21px', color: '#5D665F', margin: '4px 0 16px', maxWidth: '1400px' }) + '">' + note + '</div><div style="' + st({ display: 'flex', gap: '48px', alignItems: 'flex-start' }) + '">' + consoleFrame(quiet) + '<div><div style="' + st({ fontSize: '13px', color: '#5D665F', marginBottom: '8px' }) + '">The pane, scrolled to the end</div>' + pane(quiet, fh) + '</div></div></div>';
  const body = row('C1', 'The daily report in place of the dashboards: a busy morning', 'Inbox and Today on top, then the General Manager\'s report: one headline, up to four findings (each one line with its number and comparison, one chart from a small set, one line of why, one link), then what is on plan in a single line. Long analysis stays in Full report. Dashboards are one tap away at the bottom. Your own section is the Inbox above, so the report does not repeat it.', false, 1580) +
    row('C2', 'The same on a quiet morning', 'Nothing off plan: no findings, the headline says so, and Home gets short.', true, 760);
  const sh = fs.readFileSync(shell, 'utf8'), pre = sh.slice(0, sh.indexOf('<div style="width: 1760px;')).replace(/<title>[^<]*<\/title>/, '<title>Home with the daily report</title>');
  const html = pre + '<div style="' + st({ width: '2052px', padding: '40px 48px 56px', boxSizing: 'border-box', background: '#F3F4F1', fontFamily: "'Geist', system-ui, sans-serif", color: '#111511', WebkitFontSmoothing: 'antialiased' }) + '"><h1 style="margin: 0; font-size: 26px; line-height: 34px; font-weight: 600; letter-spacing: -.02em;">Home with the daily report</h1><div style="margin-top: 6px; font-size: 15px; color: #5D665F;">The agents choose what to show each day; the format stays fixed so it reads the same every morning.</div>' + body + '</div>\n</x-dc>\n</body>\n</html>\n';
  fs.writeFileSync(out, html); console.log('wrote', out, Math.round(html.length / 1024) + ' KB');
})();
